package com.shopstream.demo;

import io.lettuce.core.RedisClient;
import io.lettuce.core.RedisURI;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;

public class LettuceHello {

    public static void main(String[] args) {
        RedisURI uri = RedisURI.Builder.redis("localhost", 6379).build();
        RedisClient client = RedisClient.create(uri);
        try (StatefulRedisConnection<String, String> connection = client.connect()) {
            RedisCommands<String, String> redis = connection.sync();
            redis.set("greeting", "hello");
            System.out.println(redis.get("greeting"));
            redis.hset("product:42", "name", "Kettle");
            System.out.println(redis.hgetall("product:42"));
        } finally {
            client.shutdown();
        }
    }
}

package com.shopstream.demo;

import io.lettuce.core.RedisClient;
import io.lettuce.core.RedisFuture;
import io.lettuce.core.api.StatefulRedisConnection;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import reactor.core.publisher.Mono;

public class ThreeApis {

    public static void main(String[] args) throws ExecutionException, InterruptedException {
        RedisClient client = RedisClient.create("redis://localhost:6379");
        try (StatefulRedisConnection<String, String> connection = client.connect()) {

            // 1. synchronous
            String a = connection.sync().get("stock:sku-1");

            // 2. asynchronous: fire several commands without waiting, then collect
            RedisFuture<String> f1 = connection.async().get("stock:sku-1");
            RedisFuture<String> f2 = connection.async().get("stock:sku-2");
            CompletableFuture<String> both =
                f1.toCompletableFuture().thenCombine(f2, (x, y) -> x + "/" + y);
            System.out.println(both.get());
            // 3. reactive: nothing happens until subscribe/block
            Mono<String> m = connection.reactive().get("stock:sku-1");
            System.out.println(m.block());
            System.out.println(a);
        } finally {
            client.shutdown();
        }
    }
}

