import io.lettuce.core.codec.ByteArrayCodec;
import io.lettuce.core.codec.RedisCodec;
import io.lettuce.core.codec.StringCodec;

public class Codecs {

    public static void main(String[] args) {
        RedisClient client = RedisClient.create("redis://localhost:6379");

        // String keys, byte[] values: a common choice when you serialize objects yourself
        RedisCodec<String, byte[]> mixed = RedisCodec.of(StringCodec.UTF8, ByteArrayCodec.INSTANCE);
        try (StatefulRedisConnection<String, byte[]> connection = client.connect(mixed)) {
            connection.sync().set("blob:1", new byte[] {1, 2, 3});
        } finally {
            client.shutdown();
        }
    }
}

package com.shopstream.demo;

import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.support.ConnectionPoolSupport;
import org.apache.commons.pool2.impl.GenericObjectPool;
import org.apache.commons.pool2.impl.GenericObjectPoolConfig;

public class LettucePool {

    public static void main(String[] args) throws Exception {
        RedisClient client = RedisClient.create("redis://localhost:6379");
        GenericObjectPoolConfig<StatefulRedisConnection<String, String>> config =
            new GenericObjectPoolConfig<>();
        config.setMaxTotal(8);

        try (GenericObjectPool<StatefulRedisConnection<String, String>> pool =
                 ConnectionPoolSupport.createGenericObjectPool(client::connect, config)) {
            try (StatefulRedisConnection<String, String> connection = pool.borrowObject()) {
                connection.sync().set("k", "v");
            } // close() returns the connection to the pool
        } finally {
            client.shutdown();
        }
    }
}

