import io.lettuce.core.ClientOptions;
import io.lettuce.core.RedisClient;
import io.lettuce.core.SocketOptions;
import io.lettuce.core.TimeoutOptions;
import java.time.Duration;

public class LettuceOptions {

    public static RedisClient create() {
        RedisClient client = RedisClient.create("redis://localhost:6379");
        client.setOptions(ClientOptions.builder()
            .autoReconnect(true)
            .socketOptions(SocketOptions.builder()
                .connectTimeout(Duration.ofSeconds(2))
                .keepAlive(true)
                .build())
            .timeoutOptions(TimeoutOptions.enabled(Duration.ofMillis(500)))
            .build());
        return client;
    }
}

package com.shopstream.demo;

import io.lettuce.core.ReadFrom;
import io.lettuce.core.RedisClient;
import io.lettuce.core.RedisURI;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.cluster.ClusterClientOptions;
import io.lettuce.core.cluster.ClusterTopologyRefreshOptions;
import io.lettuce.core.cluster.RedisClusterClient;
import io.lettuce.core.cluster.api.StatefulRedisClusterConnection;
import io.lettuce.core.codec.StringCodec;
import io.lettuce.core.masterreplica.MasterReplica;
import io.lettuce.core.masterreplica.StatefulRedisMasterReplicaConnection;
import java.util.concurrent.TimeUnit;
import io.lettuce.core.cluster.ClusterTopologyRefreshOptions.RefreshTrigger;

public class Topologies {

    // Sentinel-managed primary with replica reads
    static StatefulRedisMasterReplicaConnection<String, String> sentinel() {
        RedisURI uri = RedisURI.Builder.sentinel("sentinel-1", 26379, "mymaster")
            .withSentinel("sentinel-2", 26379)
            .withSentinel("sentinel-3", 26379)
            .build();
        RedisClient client = RedisClient.create();
        StatefulRedisMasterReplicaConnection<String, String> connection =
            MasterReplica.connect(client, StringCodec.UTF8, uri);
        connection.setReadFrom(ReadFrom.REPLICA_PREFERRED);
        return connection;
    }

    // Redis Cluster with topology refresh
    static StatefulRedisClusterConnection<String, String> cluster() {
        RedisURI seed = RedisURI.create("redis://node-1:6379");
        RedisClusterClient client = RedisClusterClient.create(seed);
        ClusterTopologyRefreshOptions refresh = ClusterTopologyRefreshOptions.builder()
            .enablePeriodicRefresh(30, TimeUnit.SECONDS)
            .enableAdaptiveRefreshTrigger(RefreshTrigger.MOVED_REDIRECT,
                                          RefreshTrigger.PERSISTENT_RECONNECTS)
            .build();
        client.setOptions(ClusterClientOptions.builder()
            .topologyRefreshOptions(refresh)
            .build());
        return client.connect();
    }
}

