import java.time.Duration;
import redis.clients.jedis.ConnectionPoolConfig;
import redis.clients.jedis.RedisClient;

public class JedisHello {

    public static void main(String[] args) {
        ConnectionPoolConfig pool = new ConnectionPoolConfig();
        pool.setMaxTotal(16);
        pool.setMaxIdle(16);
        pool.setMinIdle(2);
        pool.setBlockWhenExhausted(true);
        pool.setMaxWait(Duration.ofMillis(500));
        pool.setTestWhileIdle(true);

        try (RedisClient jedis = RedisClient.builder()
                .hostAndPort("localhost", 6379)
                .poolConfig(pool)
                .build()) {
            jedis.set("greeting", "hello");
            System.out.println(jedis.get("greeting"));
            jedis.zadd("lb:bestsellers:daily", 12.0, "sku-1");
            System.out.println(jedis.zrevrangeWithScores("lb:bestsellers:daily", 0, 2));
        }
    }
}

