package com.shopstream.demo;

import java.util.List;
import redis.clients.jedis.AbstractPipeline;
import redis.clients.jedis.AbstractTransaction;
import redis.clients.jedis.RedisClient;
import redis.clients.jedis.Response;

public class JedisPipeline {

    static void pipeline(RedisClient jedis) {
        try (AbstractPipeline pipe = jedis.pipelined()) {
            Response<String> a = pipe.get("stock:sku-1");
            Response<String> b = pipe.get("stock:sku-2");
            pipe.sync();
            System.out.println(a.get() + " " + b.get());
        }
    }

    static void transaction(RedisClient jedis) {
        try (AbstractTransaction trans = jedis.multi()) {
            trans.incrBy("counter:orders", 1);
            trans.incrBy("counter:items", 3);
            List<Object> results = trans.exec();
            System.out.println(results);
        }
    }

    static boolean optimistic(RedisClient jedis) {
        try (AbstractTransaction trans = jedis.transaction(false)) {
            trans.watch("cart:7:version");
            trans.multi();
            Response<Long> r = trans.incr("cart:7:version");
            List<Object> results = trans.exec();
            return results != null && r.get() != null; // null results means aborted: retry
        }
    }
}

