package com.shopstream.demo;

import java.util.concurrent.TimeUnit;
import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;

public class RedissonLockDemo {

    private final RedissonClient redisson;

    public RedissonLockDemo(RedissonClient redisson) {
        this.redisson = redisson;
    }

    public void processOrder(String orderId) throws InterruptedException {
        RLock lock = redisson.getLock("lock:order:" + orderId);
        // wait up to 2 s to get the lock; with no lease time the watchdog keeps renewing it
        if (lock.tryLock(2, TimeUnit.SECONDS)) {
            try {
                // critical section
            } finally {
                lock.unlock();
            }
        } else {
            throw new IllegalStateException("order " + orderId + " is being processed");
        }
    }
}

package com.shopstream.demo;

import java.time.Duration;
import org.redisson.api.RMap;
import org.redisson.api.RRateLimiter;
import org.redisson.api.RateType;
import org.redisson.api.RedissonClient;

public class RedissonMore {

    static boolean allow(RedissonClient redisson, String apiKey) {
        RRateLimiter limiter = redisson.getRateLimiter("rl:api:" + apiKey);
        // 100 permits per second across all clients; only sets the rate if not set already
        limiter.trySetRate(RateType.OVERALL, 100, Duration.ofSeconds(1));
        return limiter.tryAcquire();
    }

    static void cartExample(RedissonClient redisson) {
        RMap<String, Integer> cart = redisson.getMap("cart:42");
        cart.put("sku-1", 2);
        int qty = cart.get("sku-1");
        System.out.println(qty);
    }
}

package com.shopstream.demo;

import java.util.Optional;
import java.util.function.Function;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.StringRedisTemplate;

public class CatalogLookup {

    private static final Logger log = LoggerFactory.getLogger(CatalogLookup.class);

    private final StringRedisTemplate redis;
    private final Function<String, String> database;

    public CatalogLookup(StringRedisTemplate redis, Function<String, String> database) {
        this.redis = redis;
        this.database = database;
    }

    public String findProductJson(String id) {
        String key = "product:" + id;
        Optional<String> cached = readQuietly(key);
        if (cached.isPresent()) {
            return cached.get();
        }
        return database.apply(id); // source of truth; may be slower
    }

    private Optional<String> readQuietly(String key) {
        try {
            return Optional.ofNullable(redis.opsForValue().get(key));
        } catch (DataAccessException e) {
            log.warn("Redis read failed for {}: {}", key, e.getMessage());
            return Optional.empty(); // degrade: treat as a cache miss
        }
    }
}
